import React, { useEffect, useState } from "react";
import { useNavigate, useParams, useLocation } from "react-router-dom";
import { CheckCircle } from "lucide-react";

const Sidebar = ({ showButton = true }) => {
  const navigate = useNavigate();
  const { id } = useParams();
  const location = useLocation();

  // Lista de módulos
  const modulos = [
    { id: 1, nome: "Aula 01 - Bem Vindo ao Curso de Formação em Liderança" },
    { id: 2, nome: "Aula 02 - O que ninguém te contou sobre a liderança" },
    { id: 3, nome: "Aula 03 - O caminho do desenvolvimento" },
    { id: 4, nome: "Aula 04 - Como conectar paixão, talento e propósito" },
    { id: 5, nome: "Aula 05 - Uma carreira de sucesso" },
    { id: 6, nome: "Aula 06 - Como conectar uma carreira de sucesso" },
  ];

  // Estado de progresso (aulas concluídas)
  const [concluidas, setConcluidas] = useState(() => {
    const salvo = localStorage.getItem("aulasConcluidas");
    return salvo ? JSON.parse(salvo) : [];
  });

  // Marca automaticamente a aula atual como concluída
  useEffect(() => {
    if (location.pathname.startsWith("/video/") && id) {
      const idNum = Number(id);
      setConcluidas((prev) => {
        const atualizado = prev.includes(idNum) ? prev : [...prev, idNum];
        localStorage.setItem("aulasConcluidas", JSON.stringify(atualizado));
        return atualizado;
      });
    }
  }, [id, location.pathname]);

  return (
    <aside className="w-72 bg-gradient-to-b from-[#B95758] to-[#e14d3a] text-white p-6 fixed top-0 left-0 h-full flex flex-col justify-between shadow-lg">
      <div>
        <h2 className="text-lg font-bold mb-6 uppercase tracking-wide">MÓDULOS</h2>

        <ul className="space-y-3 text-sm">
          {modulos.map((modulo) => {
            const isAtiva = Number(id) === modulo.id;
            const isConcluida = concluidas.includes(modulo.id);

            return (
              <li
                key={modulo.id}
                onClick={() => navigate(`/video/${modulo.id}`)}
                className={`relative flex items-center justify-between cursor-pointer px-2 py-2 rounded-md transition-all duration-200 ${
                  isAtiva ? "bg-[#ffffff14]" : "hover:bg-[#ffffff1a]"
                }`}
              >
                {/* Barrinha amarela lateral esquerda */}
                {isAtiva && (
                  <span className="absolute left-0 top-0 h-full w-1 bg-yellow-400 rounded-r-md"></span>
                )}

                <span
                  className={`ml-2 pr-2 ${
                    isAtiva ? "text-yellow-200 font-semibold" : "text-white"
                  }`}
                >
                  {modulo.nome}
                </span>

                {/* Check verde quando concluída */}
                {isConcluida && (
                  <CheckCircle
                    size={18}
                    className="text-green-300 flex-shrink-0 ml-2"
                  />
                )}
              </li>
            );
          })}
        </ul>
      </div>

      {showButton && (
        <button
          onClick={() => navigate(`/materiais/${id || 1}`)}
          className="w-full bg-white text-[#B95758] font-semibold py-2 rounded-md hover:bg-gray-100 transition shadow-sm"
        >
          Material de Apoio
        </button>
      )}
    </aside>
  );
};

export default Sidebar;
